Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
#define For(i,a,b) for(int i=a;i<b;i++)
#define pb push_back
#define mod 1000000007
#define reset(s,val) memset(s,val,sizeof(s))
#define eps 1e-8
#define pi acos(-1)
#define sqr(x) (x)*(x)
#define two(x) (1<<(x))

long long p,k,vst[1000006],ans;

long long f(long long x,long long y){
    long long res=1;
    for(long long i=30;i>=0;i--)
    {
        res*=res;
        res%=mod;
        if((1ll<<i)&y) res*=x;
        res%=mod;
    }
    return res;
}

int main( ){
    //freopen("input.txt","r",stdin);
    //freopen("output.txt","w",stdout);
    ios::sync_with_stdio(0);
    ans=0;
    cin>>p>>k;
    if(k==1)
    {
        cout<<f(p,p);return 0;
    }
    For(i,1,p) if(!vst[i])
    {
        vst[i]=1;
        ans++;
        long long cur=(i*k)%p;
        while(!vst[cur])
        {
            vst[cur]=1;
            cur=(cur*k)%p;
        }
    }
    cout<<f(p,ans);
}

